param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$SourceSha256)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
if((Get-FileHash $SourcePath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $SourceSha256){throw 'Manifest changed'}
$m=[IO.File]::ReadAllText($SourcePath)|ConvertFrom-Json
if((Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $m.worker_sha256){throw 'Worker changed'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$completed=0
foreach($case in $m.cases){
 $arguments=@($case.paths)+@([string]$case.position)
 if($arguments.Count -ne 7){throw 'Probe argument count'}
 if((Get-FileHash $m.executable.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $m.executable.sha256){throw 'Probe changed'}
 $info=[Diagnostics.ProcessStartInfo]::new();$info.FileName=$m.executable.path
 $info.Arguments=(@($arguments|ForEach-Object {'"'+([string]$_).Replace('"','\"')+'"'}) -join ' ')
 $info.WorkingDirectory=$m.repo;$info.UseShellExecute=$false;$info.CreateNoWindow=$true
 $info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true
 $process=[Diagnostics.Process]::new();$process.StartInfo=$info;$clock=[Diagnostics.Stopwatch]::StartNew()
 try{
  if(-not $process.Start()){throw 'Probe did not start'}
  $stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync()
  if(-not $process.WaitForExit([int]$m.case_timeout_seconds*1000)){
   try{$process.Kill()}catch{};$null=$process.WaitForExit(5000);throw ('Probe timeout: '+$case.name)
  }
  $process.WaitForExit();$clock.Stop()
  $out=$stdout.GetAwaiter().GetResult();$err=$stderr.GetAwaiter().GetResult();$code=$process.ExitCode
  [IO.File]::WriteAllText((Join-Path $m.output ($case.name+'.stdout.jsonl')),$out,[Text.UTF8Encoding]::new($false))
  [IO.File]::WriteAllText((Join-Path $m.output ($case.name+'.stderr.log')),$err,[Text.UTF8Encoding]::new($false))
  $rows=@(($out -split "`r?`n")|Where-Object {$_.Length -gt 0}|ForEach-Object {$_|ConvertFrom-Json})
  $layouts=@($rows|Select-Object -First 2);$inputs=if($rows.Count -eq 3){$rows[2]}else{$null}
  [ordered]@{kind='step124_original_convolution_gpu_case';case=$case.name;position=$case.position;layer=$case.layer;input_token_id=$case.input_token_id;executable_sha256=$m.executable.sha256;exit_code=$code;elapsed_ms=$clock.Elapsed.TotalMilliseconds;layouts=$layouts;inputs=$inputs}|ConvertTo-Json -Depth 10 -Compress
  if($code -ne 0 -or $rows.Count -ne 3){throw ('Probe failed: '+$case.name)}
  if($layouts[0].ring_storage -ne 'bf16' -or $layouts[1].ring_storage -ne 'f32'){throw 'Missing ring layout'}
  foreach($row in $layouts){
   if($row.kind -ne 'original_q1_convolution_native_replay' -or $row.position -ne $case.position -or -not $row.passed -or
      $row.output_cells -ne 8192 -or $row.active_history_cells -ne 24576 -or $row.output_bf16_mismatches -ne 0 -or
      $row.output_f32_carrier_bit_mismatches -ne 0 -or $row.active_history_bf16_mismatches -ne 0 -or $row.stored_current_mismatches -ne 0 -or
      $row.unowned_ring_mismatches -ne 0 -or $row.guard_mismatches -ne 0 -or -not $row.reference_padding_unchanged -or
      -not $row.current_input_immutable -or -not $row.out_of_range_block_checked -or $row.inference_acceptance){throw 'Convolution numerical comparison failed'}
  }
  if($inputs.kind -ne 'original_q1_convolution_native_inputs' -or -not $inputs.immutable_inputs -or
     $inputs.reference_output_is_compute_input -or $inputs.inference_acceptance){throw 'Immutable input boundary failed'}
  ++$completed
 }finally{$process.Dispose()}
}
if($completed -ne 90){throw 'Incomplete case set'}
[ordered]@{kind='step124_original_convolution_gpu_complete';cases=$completed;layouts=$completed*2;model_loaded=$false;inference_acceptance=$false}|ConvertTo-Json -Compress
